import { createPointMarkerElement } from "./map-components/point";

async function renderNormalPoint(map: google.maps.Map, position: google.maps.LatLngLiteral, variant: "default" | "muted" | "completed" | "emphasized") {
  const { AdvancedMarkerElement } = await google.maps.importLibrary("marker");
  const content = createPointMarkerElement({
    family: "normal",
    label: "Normal point",
    style: "dot",
    variant,
  });

  return new AdvancedMarkerElement({
    anchorLeft: "-50%",
    anchorTop: "-50%",
    content,
    map,
    position,
  });
}

