cumulativeLocation.code:
import { createPointMarkerElement } from "./map-components/point";

interface ClusterNode {
  count: number;
  position: google.maps.LatLngLiteral;
  children?: ClusterNode[];
}

async function renderCluster(map: google.maps.Map, node: ClusterNode, zoom: number) {
  const { AdvancedMarkerElement } = await google.maps.importLibrary("marker");
  const isLeaf = zoom >= 7 && !node.children?.length;
  const content = createPointMarkerElement({
    count: node.count,
    family: isLeaf ? "normal" : "cumulative",
    label: isLeaf ? "Normal point" : `${node.count} locations`,
    style: "dot",
    variant: "default",
  });

  return new AdvancedMarkerElement({
    anchorLeft: "-50%",
    anchorTop: "-50%",
    content,
    map,
    position: node.position,
  });
}

