const cachedRoutePath = [{ lat: 31.1939, lng: 121.3382 }, ...];

async function renderRouteWithNormalLocation(map: google.maps.Map) {
  const outline = new google.maps.Polyline({ map, path: cachedRoutePath, strokeColor: "#fff", strokeWeight: 12 });
  const route = new google.maps.Polyline({ map, path: cachedRoutePath, strokeColor: "#2A3EF4", strokeWeight: 8, icons: arrowIcons });

  const { AdvancedMarkerElement } = await google.maps.importLibrary("marker");
  new AdvancedMarkerElement({ map, position: cachedRoutePath[0], content: createNormalPoint() });
  new AdvancedMarkerElement({ map, position: cachedRoutePath.at(-1), content: createNormalPoint() });

  return { outline, route };
}

