const routePath = [{ lat: 31.1939, lng: 121.3382 }, ...];
const progressRatio = 0.58;

function renderRouteWithProgress(map: google.maps.Map) {
  const { completedPath, remainingPath, progressPoint } = splitRouteAtRatio(routePath, progressRatio);

  drawRouteSegment(completedPath, { color: "#9C9EAD" });
  drawRouteSegment(remainingPath, { color: "#2A3EF4", arrows: true });
  renderNormalPoint(routePath[0]);
  renderProgressPoint(progressPoint);
  renderNormalPoint(routePath.at(-1));
}

