type RegionSelectionState = "default" | "disabled" | "selected";

const regionStyle = {
  default: { fillColor: "#2A3EF4", fillOpacity: 0.1, strokeColor: "#2A3EF4", strokeWeight: 2 },
  disabled: { fillColor: "#2A3EF4", fillOpacity: 0.06, strokeColor: "#C9D2FC", strokeWeight: 2 },
  selected: { fillColor: "#2A3EF4", fillOpacity: 0.4, strokeColor: "#2A3EF4", strokeWeight: 2 },
};

function renderRegionSelection(dataLayer: google.maps.Data, selectedId?: string, hoveredId?: string) {
  dataLayer.setStyle((feature) => {
    const id = String(feature.getProperty("mapLabId") ?? "");
    return id === selectedId || id === hoveredId ? regionStyle.selected : regionStyle.default;
  });
}
